@gene('Z17b', 'skip listing option kinds this policy never takes; carry an altar lock and offer it only with enemies in sight', parents=['s1'])
def consider(kind: Num) -> Bool:
    if kind == BUY:
        return can_shop()
    if kind == CAST:
        return slot_ready(0) or slot_ready(1)
    if kind == BUY_LOCK:
        return can_shop() and not has_lock()
    if kind == LOCK:
        return has_lock() and size(enemy_tiles()) > 0
    return not (kind == WARD or kind == CANCEL)
